            v = grid[r][c]
            if v != bg:
                positions_by_value[v] = positions_by_value.get(v, []) + [(r, c)]

    # For each value, check if anchor positions share a consistent diagonal
    for v, pos_list in positions_by_value.items():
        if not pos_list:
            continue

        # Get the first position
        r0, c0 = pos_list[0]

        # Check main diagonal consistency (r-c)
        diff0 = r0 - c0
        all_same_main = True
        for r, c in pos_list[1:]:
            if r - c != diff0:
                all_same_main = False
                break

        # Check anti-diagonal consistency (r+c)
        s0 = r0 + c0
        all_same_anti = True
        for r, c in pos_list[1:]:
            if r + c != s0:
                all_same_anti = False
                break

        if all_same_main:
            # Extend main diagonal
            for r in range(rows):
                c = r - diff0
                if 0 <= c < cols:
                    output[r][c] = v
        elif all_same_anti:
            # Extend anti-diagonal
            for r in range(rows):
                c = s0 - r
                if 0 <= c < cols:
                    output[r][c] = v
        else:
            # Neither consistent - extend main from first position only
            for r in range(rows):
                c = r - diff0
                if 0 <= c < cols:
                    output[r][c] = v

    return output
